  function atom(){let a=t[pos++];if(a==='-')return -atom();if(a==='('){let v=sum();if(t[pos++]!==')')throw Error('公式括号错误');return v;}if(a==='x')return x;if(/^\d/.test(a||''))return Number(a);if(['clamp','floor','min','max'].includes(a)){if(t[pos++]!=='(')throw Error('公式错误');const args=[sum()];while(t[pos]===','){pos++;args.push(sum());}if(t[pos++]!==')')throw Error('公式错误');return a==='clamp'?Math.min(args[2],Math.max(args[1],args[0])):Math[a](...args);}throw Error('公式不支持');}
