  if(id==='1271')return [fixed('核心被动','anomalyProficiency',num(plain(coreData(b.a,b.core).desc[0]).match(/异常精通提升([\d.]+)/)?.[1]))];
  if(id==='1281')return [fixed('额外能力','dmgBonus',18)];
