  if(id==='1401')return [fixed('影画一','enemyDefReduction',20),{source:'影画二',key:'alice-squad-assault',primary:true,effects:[{type:'fixed',stat:'anomalyDamageBonus',value:15,target:{kind:'anomaly',settlementType:'attribute',anomalyEffects:['assault']}}]}];
